from collections import Counter


def transform(grid):
    """Overlay two panels, marking positions where both contain their shared symbol."""
    h, w = len(grid), len(grid[0])
    if w % 2 == 1:
        c = w // 2
        if len({grid[r][c] for r in range(h)}) == 1:
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
        else:
            a = b = None
    else:
        a = b = None
    if a is None and h % 2 == 1:
        r = h // 2
        if len(set(grid[r])) == 1:
            a, b = grid[:r], grid[r + 1:]
    if a is None:
        raise ValueError('No centered full separator found')
    if len(a) != len(b) or any(len(x) != len(y) for x, y in zip(a, b)):
        raise ValueError('Panels differ in size')
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    if len(shared) != 1:
        raise ValueError(f'Expected one shared color, found {shared}')
    color = next(iter(shared))
    return [[3 if x == color and y == color else color for x, y in zip(ra, rb)]
            for ra, rb in zip(a, b)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full-width/full-height separator lines sharing one color.
    row_lines = {r: grid[r][0] for r in range(h)
                 if all(v == grid[r][0] for v in grid[r])}
    col_lines = {c: grid[0][c] for c in range(w)
                 if all(grid[r][c] == grid[0][c] for r in range(h))}
    shared = [color for color in set(row_lines.values()) & set(col_lines.values())
              if any(v == color for v in row_lines.values())
              and any(v == color for v in col_lines.values())]
    if not shared:
        return [row[:] for row in grid]
    # The cross/lines use the separator color; select the most frequent other color as background.
    sep = shared[0]
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    rb = [-1] + [r for r, color in row_lines.items() if color == sep] + [h]
    cb = [-1] + [c for c, color in col_lines.items() if color == sep] + [w]
    row_bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_bands = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    # Use the occupied tile as a template and repeat it in each equal-sized tile.
    template = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            cells = [[grid[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if any(v != bg and v != sep for row in cells for v in row):
                template = cells
                break
        if template is not None:
            break
    if template is None:
        return [row[:] for row in grid]
    th, tw = len(template), len(template[0])
    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1 - r0 != th or c1 - c0 != tw:
                continue
            for dr in range(th):
                for dc in range(tw):
                    if template[dr][dc] != bg and template[dr][dc] != sep:
                        out[r0 + dr][c0 + dc] = template[dr][dc]
    return out

from math import isqrt

def transform(grid):
    h, w = len(grid), len(grid[0])
    # A t-by-t collection of t-by-t tiles separated by single blank rows/cols:
    # dimension = t*(t+1)-1.
    t = isqrt(h + 1)
    if t * (t + 1) - 1 != h or w != h:
        raise ValueError("expected a square tiled grid")
    step = t + 1

    # Read the repeated tile motif from the first tile containing 2s.
    motif = None
    for br in range(t):
        for bc in range(t):
            r0, c0 = br * step, bc * step
            tile = [grid[r0 + r][c0:c0 + t] for r in range(t)]
            if any(v == 2 for row in tile for v in row):
                motif = [row[:] for row in tile]
                break
        if motif is not None:
            break
    if motif is None:
        return [[0] * w for _ in range(h)]

    # Each 2 in the motif selects an output tile at its matrix coordinate;
    # mark the corresponding local cell in that copy with 8. All separators
    # and unselected tiles (including the solid-3 guide band) become zero.
    out = [[0] * w for _ in range(h)]
    for br in range(t):
        for bc in range(t):
            if motif[br][bc] != 2:
                continue
            r0, c0 = br * step, bc * step
            for r in range(t):
                for c in range(t):
                    out[r0 + r][c0 + c] = motif[r][c]
            out[r0 + br][c0 + bc] = 8
    return out

